// 本文件定义 / 命令同步补全和 @ 文件异步补全 TUI 组件。
package bubble

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"unicode"
	"unicode/utf8"

	tea "github.com/charmbracelet/bubbletea"
)

// completionKind 区分命令补全和文件补全。
type completionKind int

const (
	completionKindCommand completionKind = iota
	completionKindFile
)

// completion 保存补全弹窗的临时 UI 状态。
type completion struct {
	kind completionKind

	// 命令补全专用：过滤后的命令列表
	items []string

	// 文件补全专用
	atByteIndex   int      // @ 在 input.Value() 中的字节偏移
	query         string   // @ 之后到词尾的完整文本（含路径前缀）
	searchDir     string   // 解析出的搜索目录（用于判断是否需要重载）
	prefix        string   // searchDir 内的文件名前缀过滤
	allItems      []string // 目录内加载到的全部条目
	filteredItems []string // 按 prefix 过滤后的条目

	selectedIndex int
	loading       bool
}

// visibleItems 返回当前应展示在弹窗中的候选列表。
func (c *completion) visibleItems() []string {
	if c.kind == completionKindFile {
		return c.filteredItems
	}
	return c.items
}

// navigateUp 向上移动选中光标。
func (c *completion) navigateUp() {
	if c.selectedIndex > 0 {
		c.selectedIndex--
	}
}

// navigateDown 向下移动选中光标。
func (c *completion) navigateDown() {
	items := c.visibleItems()
	if c.selectedIndex < len(items)-1 {
		c.selectedIndex++
	}
}

// ──────────────────────────────────────────────────────────────────────────────
// 触发检测
// ──────────────────────────────────────────────────────────────────────────────

// detectAtTrigger 在 value 中找到最末尾的词边界 @ 触发点。
// 词边界条件：@ 位于字符串开头，或前一个字符为空白符。
// query 为 @ 之后到字符串末尾的内容；query 内不能含空白符（否则说明词已结束）。
// 如果未找到满足条件的 @，返回 (-1, "")。
func detectAtTrigger(value string) (atByteIndex int, query string) {
	runes := []rune(value)
	n := len(runes)
	if n == 0 {
		return -1, ""
	}

	// 从末尾向前扫描，找到当前"词"的起始位置。
	// 词 = 连续的非空白字符序列（位于末尾）。
	wordStart := n // 默认：末尾是空白，没有当前词
	for i := n - 1; i >= 0; i-- {
		if unicode.IsSpace(runes[i]) {
			wordStart = i + 1
			break
		}
		wordStart = i
	}

	if wordStart >= n {
		return -1, "" // 当前词为空（末尾是空白）
	}

	// 当前词必须以 @ 开头
	if runes[wordStart] != '@' {
		return -1, ""
	}

	// 词边界：@ 在行首，或前一个字符为空白
	if wordStart > 0 && !unicode.IsSpace(runes[wordStart-1]) {
		return -1, "" // @ 紧跟非空白字符，不是词边界（如 "text@foo"）
	}

	// 计算 @ 在原始字节串中的偏移
	byteOff := 0
	for _, r := range runes[:wordStart] {
		byteOff += utf8.RuneLen(r)
	}

	// query = @ 之后的全部文本
	q := string(runes[wordStart+1:])
	return byteOff, q
}

// ──────────────────────────────────────────────────────────────────────────────
// 路径解析
// ──────────────────────────────────────────────────────────────────────────────

// resolveSearchDir 根据 @ 之后的 query 解析搜索目录和文件名前缀。
//
//   - @       → (cwd, "")
//   - @foo    → (cwd, "foo")
//   - @sub/   → (cwd/sub, "")
//   - @sub/f  → (cwd/sub, "f")
//   - @~/f    → (HOME, "f")
//   - @/etc/f → ("/etc", "f")
func resolveSearchDir(query string) (dir, prefix string) {
	cwd, _ := os.Getwd()
	if cwd == "" {
		cwd = "."
	}

	switch {
	case query == "" || query == ".":
		return cwd, ""

	case query == "~":
		home, _ := os.UserHomeDir()
		return home, ""

	case strings.HasPrefix(query, "~/"):
		home, err := os.UserHomeDir()
		if err != nil {
			return cwd, ""
		}
		return resolvePathParts(home, query[2:])

	case strings.HasPrefix(query, "/"):
		return resolvePathParts("/", query[1:])

	default:
		return resolvePathParts(cwd, query)
	}
}

// resolvePathParts 将 base/rest 分解为 (directory, filePrefix)。
// 若 rest 含路径分隔符，最后一段作为文件名前缀，其余拼入目录。
func resolvePathParts(base, rest string) (dir, prefix string) {
	if rest == "" {
		return base, ""
	}
	if !strings.Contains(rest, "/") {
		return base, rest
	}
	idx := strings.LastIndex(rest, "/")
	return filepath.Join(base, rest[:idx]), rest[idx+1:]
}

// ──────────────────────────────────────────────────────────────────────────────
// appModel 同步逻辑（在 app.go 的 isTextEditingKey 分支调用）
// ──────────────────────────────────────────────────────────────────────────────

// syncAtCompletion 检测 @ 触发并更新 m.completion。
// 需要重新加载文件时返回 tea.Cmd，否则返回 nil。
func (m *appModel) syncAtCompletion() tea.Cmd {
	// / 命令补全优先，不与 @ 同时激活
	if m.completion != nil && m.completion.kind == completionKindCommand {
		return nil
	}

	val := m.input.Value()
	atIdx, query := detectAtTrigger(val)

	if atIdx < 0 {
		// 没有触发点，清除文件补全
		if m.completion != nil && m.completion.kind == completionKindFile {
			m.clearCompletionAndRelayout()
		}
		return nil
	}

	searchDir, prefix := resolveSearchDir(query)
	useDefault := query == ""

	if m.completion == nil || m.completion.kind != completionKindFile || m.completion.searchDir != searchDir {
		// 目录发生变化或补全尚未创建：重新加载
		m.completion = &completion{
			kind:        completionKindFile,
			atByteIndex: atIdx,
			query:       query,
			searchDir:   searchDir,
			prefix:      prefix,
			loading:     true,
		}
		m.sessionPicker = nil
		return loadFilesInDirCmd(searchDir, prefix, useDefault)
	}

	// 同一目录：仅更新前缀和过滤结果
	m.completion.atByteIndex = atIdx
	m.completion.query = query
	m.completion.prefix = prefix
	filtered := filterByPrefix(m.completion.allItems, prefix)
	if useDefault && len(filtered) > 5 {
		filtered = filtered[:5]
	}
	m.completion.filteredItems = filtered
	if m.completion.selectedIndex >= len(filtered) {
		m.completion.selectedIndex = 0
	}
	return nil
}

// syncCommandCompletion 检测 / 命令补全并更新 m.completion。
func (m *appModel) syncCommandCompletion() {
	val := m.input.Value()
	if !strings.HasPrefix(val, "/") {
		if m.completion != nil && m.completion.kind == completionKindCommand {
			m.clearCompletionAndRelayout()
		}
		return
	}
	query := strings.TrimPrefix(val, "/")
	items := commandCompletionItems(query, m.commandRegistry)
	if len(items) == 0 {
		m.clearCompletionAndRelayout()
		return
	}
	if m.completion == nil || m.completion.kind != completionKindCommand {
		m.completion = &completion{kind: completionKindCommand, items: items, prefix: query}
	} else {
		m.completion.items = items
		m.completion.prefix = query
		if m.completion.selectedIndex >= len(items) {
			m.completion.selectedIndex = 0
		}
	}
}

// ──────────────────────────────────────────────────────────────────────────────
// 异步文件加载
// ──────────────────────────────────────────────────────────────────────────────

// loadFilesInDirCmd 异步列出 searchDir 目录下的条目，用 filePrefix 过滤。
// useDefault=true 时最多返回前 5 条。
func loadFilesInDirCmd(searchDir, filePrefix string, useDefault bool) tea.Cmd {
	return func() tea.Msg {
		entries, err := os.ReadDir(searchDir)
		if err != nil {
			return fileCompletionLoadedMsg{searchDir: searchDir}
		}

		var all []string
		for _, e := range entries {
			name := e.Name()
			if strings.HasPrefix(name, ".") {
				continue
			}
			if e.IsDir() {
				all = append(all, name+"/")
			} else {
				all = append(all, name)
			}
		}

		filtered := filterByPrefix(all, filePrefix)
		if useDefault && filePrefix == "" && len(filtered) > 5 {
			filtered = filtered[:5]
		}

		return fileCompletionLoadedMsg{
			searchDir: searchDir,
			items:     all,
			filtered:  filtered,
		}
	}
}

// filterByPrefix 筛选以 prefix 开头的条目（大小写不敏感）。
func filterByPrefix(items []string, prefix string) []string {
	if prefix == "" {
		out := make([]string, len(items))
		copy(out, items)
		return out
	}
	lower := strings.ToLower(prefix)
	var out []string
	for _, item := range items {
		if strings.HasPrefix(strings.ToLower(item), lower) {
			out = append(out, item)
		}
	}
	return out
}

// ──────────────────────────────────────────────────────────────────────────────
// 命令补全构造
// ──────────────────────────────────────────────────────────────────────────────

// newCommandCompletion 创建命令补全（同步）。
func newCommandCompletion(prefix string, registry *CommandRegistry) *completion {
	items := commandCompletionItems(prefix, registry)
	if len(items) == 0 {
		return nil
	}
	return &completion{
		kind:   completionKindCommand,
		items:  items,
		prefix: prefix,
	}
}

// commandCompletionItems 从注册表中筛选匹配前缀的命令名。
func commandCompletionItems(prefix string, registry *CommandRegistry) []string {
	if registry == nil {
		return nil
	}
	var items []string
	for _, name := range registry.order {
		if prefix == "" || strings.HasPrefix(name, "/"+prefix) {
			items = append(items, name)
		}
	}
	return items
}

// ──────────────────────────────────────────────────────────────────────────────
// 补全确认 — 写回输入框
// ──────────────────────────────────────────────────────────────────────────────

// applyFileCompletion 将选中文件写回输入框，只替换 @query 段，保留之前的文本。
// trailingSpace=true（Enter）在路径后追加空格以结束引用；false（Tab）不追加，光标停在路径末尾。
func (m appModel) applyFileCompletion(selected string, trailingSpace bool) appModel {
	if m.completion == nil {
		return m
	}
	val := m.input.Value()
	atIdx, query := detectAtTrigger(val)
	if atIdx < 0 {
		return m
	}

	before := val[:atIdx]
	ref := buildAtRef(query, m.completion.searchDir, selected)
	suffix := ""
	if trailingSpace {
		suffix = " "
	}
	m.input.SetValue(before + ref + suffix)
	m.input.CursorEnd()
	m.relayout()
	return m
}

// buildAtRef 根据原始 query 和 selected 构造 @path 引用。
// 保留 query 中的路径前缀（如 @~/ 或 @/），只替换最末的文件名片段。
func buildAtRef(query, searchDir, selected string) string {
	// 找到最后一个 / 的位置，保留 @ + 路径前缀
	if idx := strings.LastIndex(query, "/"); idx >= 0 {
		return "@" + query[:idx+1] + selected
	}
	// 没有 / 分隔符，直接 @selected
	_ = searchDir
	return "@" + selected
}

// applyCommandCompletion 将命令填入输入框。
func (m appModel) applyCommandCompletion(selected string) appModel {
	m.input.SetValue(selected + " ")
	m.input.CursorEnd()
	return m
}

func (m *appModel) clearCompletionAndRelayout() {
	if m.completion == nil {
		return
	}
	m.completion = nil
	m.relayout()
}

// ──────────────────────────────────────────────────────────────────────────────
// 渲染
// ──────────────────────────────────────────────────────────────────────────────

// renderCompletionBox 渲染补全弹窗（显示在输入框上方）。
func (m appModel) renderCompletionBox() string {
	if m.completion == nil {
		return ""
	}
	width := maxInt(32, m.width-2)
	return completionPanelStyle.Width(width).Render(m.renderCompletionContent())
}

// renderCompletionContent 渲染补全弹窗内容。
func (m appModel) renderCompletionContent() string {
	c := m.completion
	var title string
	switch c.kind {
	case completionKindCommand:
		title = wizardTitleStyle.Render("Commands")
	case completionKindFile:
		title = wizardTitleStyle.Render("Files")
	}
	lines := []string{title}

	if c.loading {
		lines = append(lines, "  Loading...")
		return strings.Join(lines, "\n")
	}

	visible := c.visibleItems()
	if len(visible) == 0 {
		lines = append(lines, "  No matches.")
		return strings.Join(lines, "\n")
	}

	maxVisible := 8
	start := 0
	if c.selectedIndex >= maxVisible {
		start = c.selectedIndex - maxVisible + 1
	}
	end := start + maxVisible
	if end > len(visible) {
		end = len(visible)
	}

	for i := start; i < end; i++ {
		label := visible[i]
		if i == c.selectedIndex {
			lines = append(lines, selectedProviderStyle.Render(fmt.Sprintf("> %s", label)))
		} else {
			lines = append(lines, unselectedProviderStyle.Render(fmt.Sprintf("  %s", label)))
		}
	}
	return strings.Join(lines, "\n")
}

// ──────────────────────────────────────────────────────────────────────────────
// 兼容占位（避免外部调用编译错误）
// ──────────────────────────────────────────────────────────────────────────────

// newFileCompletion 兼容旧调用签名。
func newFileCompletion(_ string) *completion {
	return &completion{kind: completionKindFile, loading: true}
}

// loadFileCompletionCmd 兼容旧调用，加载 cwd 默认 5 个文件。
func loadFileCompletionCmd() tea.Cmd {
	cwd, _ := os.Getwd()
	return loadFilesInDirCmd(cwd, "", true)
}

package bubble

import (
	"fmt"
	"github.com/charmbracelet/lipgloss"
	"gocode/internal/loop"
	"gocode/internal/settings"
	"math"
	"strconv"
	"strings"
	"time"
)

func (m appModel) contextMeterTitle() string {
	width := m.width
	if width <= 0 {
		width = contextMeterDefaultWidth
	}
	return m.contextMeterLine(maxInt(28, width-2))
}

func (m appModel) contextMeterLine(width int) string {
	stats := m.contextStats()
	limit := maxInt(1, stats.LimitTokens)
	rawUsed := maxInt(0, stats.UsedTokens)
	rawCache := clampInt(stats.CacheTokens, 0, rawUsed)
	// 进度条：easeOutBack（有轻微超出感，720ms）
	animatedUsed, animatedCache, pulse := m.animatedContextTokens(limit)
	// 标签数字：easeOutCubic（无超出，400ms），呈现快速计数跳动效果
	labelUsed, labelCache := m.animatedLabelTokens(rawUsed, rawCache, limit)
	usedLabel := formatContextUsageLabel(labelUsed, labelCache, limit, m.isGenerating)
	freeLabel := formatContextFreeLabel(labelUsed, limit)
	return renderContextMeterLine(width, usedLabel, freeLabel, animatedUsed, animatedCache, limit, m.thinkingLabel(), pulse)
}

func formatContextUsageLabel(used, cache, limit int, isGenerating bool) string {
	arrow := contextDirectionArrow(isGenerating)
	parts := []string{formatCompactTokenCount(used) + arrow}
	parts = append(parts, fmt.Sprintf("%s(%s)", formatContextPercent(used, limit), formatContextPercent(cache, limit)))
	return strings.Join(parts, " ")
}

func formatContextFreeLabel(used, limit int) string {
	free := maxInt(0, limit-used)
	return fmt.Sprintf("free(%s)", formatContextPercent(free, limit))
}

// contextDirectionArrow returns "↓" during generation, "↑" otherwise.
func contextDirectionArrow(isGenerating bool) string {
	if isGenerating {
		return "↓"
	}
	return "↑"
}

func formatContextPercent(value, total int) string {
	return fmt.Sprintf("%.0f%%", percent(clampInt(value, 0, maxInt(0, total)), total))
}

func formatCompactTokenCount(value int) string {
	value = maxInt(0, value)
	if value <= 999 {
		return strconv.Itoa(value)
	}
	scaled := float64(value) / 1000
	unit := "k"
	if value > 999000 {
		scaled = float64(value) / 1000000
		unit = "M"
	}
	text := formatThreeDigitNumber(scaled)
	if unit == "k" && strings.HasPrefix(text, "1000") {
		text = formatThreeDigitNumber(float64(value) / 1000000)
		unit = "M"
	}
	return text + unit
}

func formatThreeDigitNumber(value float64) string {
	switch {
	case value >= 100:
		return fmt.Sprintf("%.0f", value)
	case value >= 10:
		return trimTrailingDecimalZeros(fmt.Sprintf("%.1f", value))
	default:
		return trimTrailingDecimalZeros(fmt.Sprintf("%.2f", value))
	}
}

func trimTrailingDecimalZeros(text string) string {
	text = strings.TrimRight(text, "0")
	return strings.TrimRight(text, ".")
}

func (m appModel) contextStats() loop.ContextStats {
	cfg := m.currentSettings()
	limit := cfg.UI.ContextLimitTokens
	if provider, ok := m.runner.(contextStatsProvider); ok {
		return provider.ContextStats(limit, m.input.Value())
	}
	return loop.ContextStats{LimitTokens: limit}
}

func (m appModel) currentSettings() settings.Config {
	if m.settingsConfig == nil {
		return settings.DefaultConfig()
	}
	return settings.Normalize(m.settingsConfig.CurrentSettings())
}

func (m appModel) thinkingLabel() string {
	if !m.isModelWorkRunning() || m.turnStartedAt.IsZero() {
		return ""
	}
	now := m.cursorFrameAt
	if now.IsZero() {
		now = time.Now()
	}
	elapsed := now.Sub(m.turnStartedAt)
	if elapsed < 0 {
		elapsed = 0
	}
	return fmt.Sprintf("<thinking %ds>", int(elapsed.Seconds()))
}

func contextBarWidth(width int, usedLabel, freeLabel string) int {
	width = maxInt(1, width)
	barWidth := width - lipgloss.Width(usedLabel) - lipgloss.Width(freeLabel) - 2
	if barWidth >= 8 {
		return barWidth
	}
	return maxInt(contextMeterMinimumBarCells, width-lipgloss.Width(compactContextLabel(usedLabel))-lipgloss.Width(compactContextLabel(freeLabel))-2)
}

func compactContextLabel(label string) string {
	if strings.HasPrefix(label, "free(") {
		return "free"
	}
	fields := strings.Fields(label)
	if len(fields) == 0 {
		return label
	}
	if len(fields) <= 2 {
		return fields[0]
	}
	return strings.Join(fields[:2], " ")
}

func renderContextMeterLine(width int, usedLabel, freeLabel string, used, cache, limit int, overlay string, pulse float64) string {
	width = maxInt(1, width)
	barWidth := contextBarWidth(width, usedLabel, freeLabel)
	if barWidth+lipgloss.Width(usedLabel)+lipgloss.Width(freeLabel)+2 > width {
		usedLabel = compactContextLabel(usedLabel)
		freeLabel = compactContextLabel(freeLabel)
	}
	usedText := contextUsedStyle.Render(usedLabel)
	freeText := contextFreeStyle.Render(freeLabel)
	barWidth = maxInt(contextMeterMinimumBarCells, width-lipgloss.Width(usedLabel)-lipgloss.Width(freeLabel)-2)
	barOffset := lipgloss.Width(usedLabel) + 1
	overlayStart := centeredOverlayStart(width, barOffset, barWidth, overlay)
	bar := renderContextBarWithOverlayStart(used, cache, limit, barWidth, overlay, overlayStart, pulse)
	line := usedText + " " + bar + " " + freeText
	if visible := lipgloss.Width(line); visible < width {
		line += strings.Repeat(" ", width-visible)
	}
	return line
}

func renderContextBar(used, cache, limit, width int, overlay string) string {
	overlayStart := -1
	if overlayWidth := lipgloss.Width(overlay); overlayWidth > 0 && overlayWidth <= width {
		overlayStart = (width - overlayWidth) / 2
	}
	return renderContextBarWithOverlayStart(used, cache, limit, width, overlay, overlayStart, 0)
}

func renderContextBarWithOverlayStart(used, cache, limit, width int, overlay string, overlayStart int, pulse float64) string {
	limit = maxInt(1, limit)
	width = maxInt(contextMeterMinimumBarCells, width)
	usedCells := int(math.Round(float64(clampInt(used, 0, limit)) / float64(limit) * float64(width)))
	cacheCells := int(math.Round(float64(clampInt(cache, 0, used)) / float64(limit) * float64(width)))
	if cacheCells > usedCells {
		cacheCells = usedCells
	}
	cells := make([]string, width)
	for i := 0; i < width; i++ {
		switch {
		case i < cacheCells:
			cells[i] = contextCacheStyle.Render("▰")
		case i < usedCells:
			cells[i] = contextUsedPulseStyle(pulse, i, usedCells).Render("▰")
		default:
			cells[i] = contextFreeStyle.Render("▱")
		}
	}
	overlayRunes := []rune(overlay)
	if len(overlayRunes) > 0 && overlayStart >= 0 && overlayStart+len(overlayRunes) <= width {
		for i, r := range overlayRunes {
			cells[overlayStart+i] = contextThinkingStyle.Render(string(r))
		}
	}
	return strings.Join(cells, "")
}

func (m *appModel) updateContextMeterAnimation() {
	now := m.animationNow()
	stats := m.contextStats()
	limit := maxInt(1, stats.LimitTokens)
	used := clampInt(maxInt(0, stats.UsedTokens), 0, limit)
	cache := clampInt(stats.CacheTokens, 0, used)
	if !m.contextMeter.initialized {
		m.contextMeter = contextMeterAnimation{
			initialized: true,
			startedAt:   now,
			fromUsed:    float64(used),
			fromCache:   float64(cache),
			targetUsed:  used,
			targetCache: cache,
		}
		return
	}
	if m.contextMeter.targetUsed == used && m.contextMeter.targetCache == cache {
		return
	}
	currentUsed, currentCache, _ := m.animatedContextTokens(limit)
	m.contextMeter.startedAt = now
	m.contextMeter.fromUsed = float64(currentUsed)
	m.contextMeter.fromCache = float64(currentCache)
	m.contextMeter.targetUsed = used
	m.contextMeter.targetCache = cache
}

func (m appModel) animatedContextTokens(limit int) (int, int, float64) {
	if !m.contextMeter.initialized {
		return m.contextMeter.targetUsed, m.contextMeter.targetCache, 0
	}
	now := m.animationNow()
	elapsed := now.Sub(m.contextMeter.startedAt)
	if elapsed < 0 {
		elapsed = 0
	}
	const duration = 720 * time.Millisecond
	progress := clamp01(float64(elapsed) / float64(duration))
	eased := easeOutBack(progress)
	animatedUsed := int(math.Round(lerp(m.contextMeter.fromUsed, float64(m.contextMeter.targetUsed), eased)))
	animatedCache := int(math.Round(lerp(m.contextMeter.fromCache, float64(m.contextMeter.targetCache), eased)))
	animatedUsed = clampInt(animatedUsed, 0, limit)
	animatedCache = clampInt(animatedCache, 0, animatedUsed)
	return animatedUsed, animatedCache, contextPulse(progress)
}

// animatedLabelTokens 用 easeOutCubic + 400ms 为数字标签计算动画值。
// 动画未初始化时回退到 rawUsed/rawCache（立即显示真实值）。
func (m appModel) animatedLabelTokens(rawUsed, rawCache, limit int) (used, cache int) {
	if !m.contextMeter.initialized {
		return clampInt(rawUsed, 0, limit), clampInt(rawCache, 0, clampInt(rawUsed, 0, limit))
	}
	now := m.animationNow()
	elapsed := now.Sub(m.contextMeter.startedAt)
	if elapsed < 0 {
		elapsed = 0
	}
	const labelDuration = 400 * time.Millisecond
	progress := clamp01(float64(elapsed) / float64(labelDuration))
	eased := easeOutCubic(progress)
	animUsed := int(math.Round(lerp(m.contextMeter.fromUsed, float64(m.contextMeter.targetUsed), eased)))
	animCache := int(math.Round(lerp(m.contextMeter.fromCache, float64(m.contextMeter.targetCache), eased)))
	animUsed = clampInt(animUsed, 0, limit)
	animCache = clampInt(animCache, 0, animUsed)
	return animUsed, animCache
}

func contextPulse(progress float64) float64 {
	if progress <= 0 || progress >= 1 {
		return 0
	}
	return math.Sin(progress * math.Pi)
}

func contextUsedPulseStyle(pulse float64, index, usedCells int) lipgloss.Style {
	if pulse <= 0 || usedCells <= 0 || index < usedCells-2 {
		return contextUsedStyle
	}
	return contextUsedStyle.Copy().Foreground(colorManager.LipglossColor(colorMarkdownHeading)).Bold(true)
}

func lerp(from, to, t float64) float64 {
	return from + (to-from)*t
}

func easeOutBack(t float64) float64 {
	t = clamp01(t)
	const c1 = 1.70158
	const c3 = c1 + 1
	x := t - 1
	return 1 + c3*x*x*x + c1*x*x
}

func centeredOverlayStart(lineWidth, barOffset, barWidth int, overlay string) int {
	overlayWidth := lipgloss.Width(overlay)
	if overlayWidth == 0 || overlayWidth > barWidth {
		return -1
	}
	start := (lineWidth-overlayWidth)/2 - barOffset
	if start < 0 || start+overlayWidth > barWidth {
		return (barWidth - overlayWidth) / 2
	}
	return start
}

func percent(value, total int) float64 {
	if total <= 0 {
		return 0
	}
	return float64(value) / float64(total) * 100
}

func clampInt(value, minValue, maxValue int) int {
	if value < minValue {
		return minValue
	}
	if value > maxValue {
		return maxValue
	}
	return value
}

// renderContextCardContent 为右侧 Context 卡片渲染多行内容。
// 输出 token 数、进度条，以及压缩后的 cache/free/turns 状态。
func (m appModel) renderContextCardContent(innerWidth int) string {
	stats := m.contextStats()
	limit := maxInt(1, stats.LimitTokens)
	rawUsed := maxInt(0, stats.UsedTokens)
	rawCache := clampInt(stats.CacheTokens, 0, rawUsed)
	labelUsed, labelCache := m.animatedLabelTokens(rawUsed, rawCache, limit)

	// Line 1: cache% left, token centre-left, free right.
	cacheLabel := "cache " + formatContextPercent(labelCache, limit)
	rawToken := formatCompactTokenCount(labelUsed) + contextDirectionArrow(m.isGenerating)
	rawFree := formatContextFreeLabel(labelUsed, limit)
	cacheVW := len([]rune(cacheLabel))
	tokenVW := len([]rune(rawToken))
	freeVW := len([]rune(rawFree))
	gap := maxInt(1, innerWidth-cacheVW-1-tokenVW-freeVW)
	topLine := contextCacheStyle.Render(cacheLabel) + " " + contextUsedStyle.Render(rawToken) + strings.Repeat(" ", gap) + contextFreeStyle.Render(rawFree)

	// Line 2: progress bar
	animatedUsed, animatedCache, _ := m.animatedContextTokens(limit)
	bar := renderContextBar(animatedUsed, animatedCache, limit, innerWidth, "")

	lines := []string{topLine, bar}
	if supplementLine := m.contextWorkStatusLine(innerWidth); supplementLine != "" {
		lines = append(lines, supplementLine)
	}

	return strings.Join(lines, "\n")
}

func centeredContextStatusLine(width int, parts ...string) string {
	return compactContextStatusLine(width, nonEmptyStrings(parts...))
}

func compactContextStatusLine(width int, options ...[]string) string {
	if width <= 0 {
		return ""
	}
	for _, parts := range options {
		visible := strings.Join(nonEmptyStrings(parts...), " · ")
		if lipgloss.Width(visible) <= width {
			return centeredContextStatusText(width, visible)
		}
	}
	if len(options) == 0 {
		return centeredContextStatusText(width, "")
	}
	fallback := strings.Join(nonEmptyStrings(options[len(options)-1]...), " ")
	return centeredContextStatusText(width, trimVisibleWidth(fallback, width))
}

func centeredContextStatusText(width int, visible string) string {
	return lipgloss.NewStyle().
		Width(width).
		Align(lipgloss.Center).
		Foreground(colorManager.LipglossColor(colorContextFree)).
		Render(visible)
}

func trimVisibleWidth(text string, width int) string {
	if width <= 0 || lipgloss.Width(text) <= width {
		return text
	}
	runes := []rune(text)
	for lipgloss.Width(string(runes)) > width && len(runes) > 0 {
		runes = runes[:len(runes)-1]
	}
	return string(runes)
}

func (m appModel) contextPercentStatusLine(width int, cachePct, freePct string) string {
	turns := m.turnsCount()
	return compactContextStatusLine(
		width,
		[]string{"cache " + cachePct, "free " + freePct, fmt.Sprintf("turns %d", turns)},
		[]string{"cache" + cachePct, "free" + freePct, fmt.Sprintf("turns%d", turns)},
		[]string{"c" + cachePct, "f" + freePct, fmt.Sprintf("t%d", turns)},
	)
}

func (m appModel) contextWorkStatusLine(width int) string {
	var full []string
	var compact []string
	var tiny []string
	if supplements := m.pendingSupplementCount(); supplements > 0 {
		full = append(full, fmt.Sprintf("supplements %d", supplements))
		compact = append(compact, fmt.Sprintf("supp %d", supplements))
		tiny = append(tiny, fmt.Sprintf("s%d", supplements))
	}
	if queued := m.chatQueue.Len(); queued > 0 {
		full = append(full, fmt.Sprintf("queued %d", queued))
		compact = append(compact, fmt.Sprintf("queue %d", queued))
		tiny = append(tiny, fmt.Sprintf("q%d", queued))
	}
	if len(full) == 0 {
		return ""
	}
	return compactContextStatusLine(width, full, compact, tiny)
}

func (m appModel) pendingSupplementCount() int {
	provider, ok := m.runner.(SupplementStatsProvider)
	if !ok {
		return 0
	}
	return provider.PendingSupplementCount()
}

// 本文件定义 Bubble Tea 主界面的布局、输入区渲染和终端光标锚点计算。
package bubble

import (
	"github.com/charmbracelet/bubbles/textarea"
	"github.com/charmbracelet/lipgloss"
	"gocode/internal/settings"
)

// View 根据当前状态渲染 header、聊天历史面板和输入面板。
func (m appModel) View() string {
	if !m.ready {
		if m.cursorAnchor != nil {
			m.cursorAnchor.clear()
		}
		return "Starting Bubble Tea..."
	}

	input := m.renderActiveInputPanel()

	// Wrap the left column in a fixed-width container so its rendered width
	// stays stable during streaming and never shifts the right sidebar.
	// Use MaxWidth (not Width) to clip without wrapping lines.
	// Also clamp height to bodyHeight so long/wrapping lines in the viewport
	// content cannot make leftContent taller than the terminal body, which
	// would otherwise shift the right panel up by the overflow amount.
	header := m.renderHeader()
	headerH := 0
	if header != "" {
		headerH = lipgloss.Height(header)
	}
	bodyHeight := maxInt(1, m.height-headerH)
	leftColWidth := maxInt(1, m.width-m.sidebarWidth)
	leftContent := lipgloss.NewStyle().MaxWidth(leftColWidth).MaxHeight(bodyHeight).Render(
		lipgloss.JoinVertical(lipgloss.Left,
			m.renderTranscriptBox(),
			input,
		),
	)
	right := m.renderRightPanel(m.sidebarWidth, bodyHeight)

	body := lipgloss.JoinHorizontal(lipgloss.Top, leftContent, right)

	var parts []string
	if header != "" {
		parts = append(parts, header)
	}
	parts = append(parts, body)
	view := lipgloss.JoinVertical(lipgloss.Left, parts...)
	m.updateTerminalCursorAnchor(input)
	return view
}

func (m appModel) renderActiveInputPanel() string {
	if m.modelWizard != nil {
		return m.renderModelWizardBox()
	}
	if m.settingWizard != nil {
		return m.renderSettingWizardBox()
	}
	if m.sessionPicker != nil {
		return m.renderSessionPickerBox()
	}
	inputBox := m.renderInputBox()
	if m.completion != nil {
		// 补全弹窗悬浮在输入框上方，输入框始终可见
		return lipgloss.JoinVertical(lipgloss.Left, m.renderCompletionBox(), inputBox)
	}
	return inputBox
}

// updateTerminalCursorAnchor 根据输入框在画面中的位置更新终端真实光标锚点。
func (m appModel) updateTerminalCursorAnchor(inputPanel string) {
	if m.cursorAnchor == nil {
		return
	}
	if !m.shouldAnchorTextInputCursor() {
		m.cursorAnchor.clear()
		return
	}
	m.cursorAnchor.set(m.inputCursorTerminalPosition(inputPanel))
}

// shouldAnchorTextInputCursor 判断当前是否应该把终端真实光标移动到输入单元格。
func (m appModel) shouldAnchorTextInputCursor() bool {
	// 补全弹窗开启时输入框仍然可见，光标仍需锚定
	return m.ready && !m.running && m.modelWizard == nil && m.settingWizard == nil && m.sessionPicker == nil
}

// inputCursorTerminalPosition 计算输入框光标相对当前帧底部的位置。
func (m appModel) inputCursorTerminalPosition(inputPanel string) terminalCursorPosition {
	inputHeight := maxInt(1, lipgloss.Height(inputPanel))
	// 补全弹窗在输入框上方时，光标行需要偏移补全框高度
	completionOffset := 0
	if m.completion != nil {
		completionOffset = lipgloss.Height(m.renderCompletionBox())
	}
	row := minInt(completionOffset+1+m.inputEmbeddedTitleHeight()+visibleTextareaCursorRow(m.input), inputHeight-1)
	upFromBottom := maxInt(0, inputHeight-row-1)
	column := 2 + visibleTextareaCursorColumn(m.input)
	if m.width > 0 {
		column = minInt(column, maxInt(0, m.width-1))
	}
	return terminalCursorPosition{
		active:       true,
		upFromBottom: upFromBottom,
		column:       maxInt(0, column),
	}
}

// inputEmbeddedTitleHeight 返回输入框内部 title 区域的行高。
func (m appModel) inputEmbeddedTitleHeight() int {
	return 0
}

// visibleTextareaCursorRow 返回 textarea 光标在当前可视输入区域中的行号。
func visibleTextareaCursorRow(input textarea.Model) int {
	lineInfo := input.LineInfo()
	row := input.Line() + lineInfo.RowOffset
	return minInt(maxInt(0, row), maxInt(0, inputVisibleLineCount(input)-1))
}

// visibleTextareaCursorColumn 返回 textarea 光标在当前可视输入区域中的列号。
func visibleTextareaCursorColumn(input textarea.Model) int {
	return maxInt(0, input.LineInfo().CharOffset)
}

// renderInputBox 渲染普通输入、多行输入、终端输入和等待状态的输入面板。
func (m appModel) renderInputBox() string {
	width := m.leftPanelContentWidth(20)
	content := m.input.View()
	style := inputPanelFocusedStyle

	if m.isTerminalInputActive() {
		style = inputPanelTerminalStyle
	}
	if m.hasMultilineInput() {
		style = inputPanelMultilineStyle
		if m.isTerminalInputActive() {
			style = inputPanelTerminalStyle
		}
	}
	if m.runningTerminal {
		style = inputPanelTerminalStyle
	}

	return style.Width(width).Render(content)
}

// renderTranscriptBox 渲染带边框的聊天历史滚动面板。
func (m appModel) renderTranscriptBox() string {
	width := m.leftPanelContentWidth(20)
	return transcriptPanelStyle.Width(width).Height(maxInt(1, m.viewport.Height)).Render(m.viewport.View())
}

func (m appModel) leftPanelContentWidth(minWidth int) int {
	leftColWidth := m.width - m.sidebarWidth
	return maxInt(minWidth, leftColWidth-transcriptPanelHorizontalFrame)
}

// renderHeader 渲染顶部状态栏。空 header 文本表示当前不展示状态栏。
func (m appModel) renderHeader() string {
	text := m.headerText()
	if text == "" {
		return ""
	}
	return headerStyle.Width(m.width).Render(text)
}

// headerHeight 返回当前布局中 header 实际占用的高度。
func (m appModel) headerHeight() int {
	return lipgloss.Height(m.renderHeader())
}

// headerText 生成顶部状态栏文本。
// TODO: 后期希望改成显示时间或者用标签页方式展示 agent 的状态。
func (m appModel) headerText() string {
	if m.currentSettings().UI.ContextMeterLocation == settings.MeterLocationHeader {
		return m.contextMeterLine(maxInt(28, m.width))
	}
	return ""
}

// relayout 根据终端尺寸和输入高度重新计算 viewport 与 textarea 尺寸。
func (m *appModel) relayout() {
	total := maxInt(40, m.width)
	m.sidebarWidth = maxInt(rightSidebarMinWidth, total*30/100)
	leftColWidth := total - m.sidebarWidth

	contentWidth := maxInt(20, leftColWidth-transcriptPanelHorizontalFrame)
	m.viewport.Width = contentWidth
	m.input.SetWidth(contentWidth)
	m.input.SetHeight(inputVisibleLineCount(m.input))

	headerHeight := m.headerHeight()
	inputHeight := lipgloss.Height(m.renderActiveInputPanel())
	availableTranscriptHeight := m.height - headerHeight - inputHeight - transcriptPanelVerticalFrame
	m.viewport.Height = maxInt(1, availableTranscriptHeight)
	m.expandTranscriptToFillHeight()
}

func (m *appModel) expandTranscriptToFillHeight() {
	if m.height <= 0 {
		return
	}
	input := m.renderActiveInputPanel()
	var parts []string
	if header := m.renderHeader(); header != "" {
		parts = append(parts, header)
	}
	parts = append(parts, m.renderTranscriptBox())
	parts = append(parts, input)
	full := lipgloss.JoinVertical(lipgloss.Left, parts...)
	if deficit := m.height - lipgloss.Height(full); deficit > 0 {
		m.viewport.Height += deficit
	}
}

// 本文件定义右侧 30% 面板的三个卡片渲染逻辑。
package bubble

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/charmbracelet/lipgloss"
	"gocode/internal/subagent"
)

const (
	pipelineCardMaxContentHeight = 12
	pipelineMaxStageRows         = 6
)

// pipelineArtifacts lists the 18 pipeline phases in order, each with display name and artifact filename.
// Artifact paths are relative to .pipeline-workspace/ (except Cleanup which is in the parent dir).
var pipelineArtifacts = [18][2]string{
	{"Brainstorm", "design.md"},
	{"Spec", "spec.json"},
	{"Plan", "plan.json"},
	{"Arch", "architecture.json"},
	{"Dispatch", "dispatch.json"},
	{"Execution", "execution-report.json"},
	{"Complexity", "execution-report.json"}, // shares artifact; detected via Merge existence
	{"Merge", "merge-report.json"},
	{"Validation", "validation-report.json"},
	{"Tree Class", "tree-classification.json"},
	{"Rubric Gen", "tree-rubrics.json"},
	{"Rubric Vfy", "tree-rubric-verification.json"},
	{"Rubric Rfn", "tree-rubrics-refined.json"},
	{"Grading", "tree-grading-individual.json"},
	{"QA", "qa-report.json"},
	{"Docs", "doc-report.json"},
	{"Assessment", "final-assessment.json"},
	{"Cleanup", ".pipeline-last-run-summary.json"}, // in parent of workspaceDir
}

// loadPipelineState scans workspaceDir and infers the current pipeline phase state.
func loadPipelineState(workspaceDir string, activeAfter time.Time) pipelineState {
	var s pipelineState
	s.activeIdx = -1
	latestArtifactAt := latestPipelineWorkspaceModTime(workspaceDir)
	if info, err := os.Stat(filepath.Join(filepath.Dir(workspaceDir), ".pipeline-last-run-summary.json")); err == nil {
		latestArtifactAt = maxTime(latestArtifactAt, info.ModTime())
	}

	// Read global iteration from execution-report.json
	iterFile := filepath.Join(workspaceDir, "execution-report.json")
	if data, err := os.ReadFile(iterFile); err == nil {
		var rep struct {
			Iteration int `json:"iteration"`
		}
		if json.Unmarshal(data, &rep) == nil && rep.Iteration > 0 {
			s.globalIter = rep.Iteration
		}
	}

	specExists := false
	if _, err := os.Stat(filepath.Join(workspaceDir, "spec.json")); err == nil {
		specExists = true
	}

	// Determine each phase's status
	lastDoneIdx := -1
	for i, pa := range pipelineArtifacts {
		artifactPath := filepath.Join(workspaceDir, pa[1])
		if pa[0] == "Cleanup" {
			artifactPath = filepath.Join(filepath.Dir(workspaceDir), pa[1])
		}
		_, err := os.Stat(artifactPath)
		exists := err == nil
		s.phases[i] = pipelinePhaseEntry{
			name:     pa[0],
			artifact: pa[1],
		}
		if exists {
			s.phases[i].status = phaseStatusDone
			s.doneCount++
			lastDoneIdx = i
		}
	}
	s.detected = specExists && pipelineWorkspaceIsActive(workspaceDir, latestArtifactAt, activeAfter)

	// Active phase = first phase after last done
	if s.detected && lastDoneIdx+1 < 18 {
		s.activeIdx = lastDoneIdx + 1
		s.phases[s.activeIdx].status = phaseStatusActive
		s.phases[s.activeIdx].iteration = s.globalIter
	}

	// Mark retry: Execution done + globalIter > 1 + Validation not done
	execDone := s.phases[5].status == phaseStatusDone
	validDone := s.phases[8].status == phaseStatusDone
	if execDone && s.globalIter > 1 && !validDone {
		for i := 5; i <= 8; i++ {
			if s.phases[i].status == phaseStatusPending {
				s.phases[i].status = phaseStatusRetry
			}
		}
	}
	return s
}

func latestPipelineWorkspaceModTime(workspaceDir string) time.Time {
	var latest time.Time
	_ = filepath.Walk(workspaceDir, func(_ string, info os.FileInfo, err error) error {
		if err != nil || info == nil {
			return nil
		}
		latest = maxTime(latest, info.ModTime())
		return nil
	})
	return latest
}

func pipelineWorkspaceIsActive(workspaceDir string, latestArtifactAt, activeAfter time.Time) bool {
	if activeAfter.IsZero() {
		return true
	}
	if pipelineActiveMarkerExists(workspaceDir, activeAfter) {
		return true
	}
	return !latestArtifactAt.IsZero() && !latestArtifactAt.Before(activeAfter)
}

func pipelineActiveMarkerExists(workspaceDir string, activeAfter time.Time) bool {
	for _, name := range []string{".active", ".pipeline-active", "active", "running", "pipeline.lock"} {
		info, err := os.Stat(filepath.Join(workspaceDir, name))
		if err == nil && !info.ModTime().Before(activeAfter) {
			return true
		}
	}

	statusPath := filepath.Join(workspaceDir, "status.json")
	info, err := os.Stat(statusPath)
	if err != nil || info.ModTime().Before(activeAfter) {
		return false
	}
	data, err := os.ReadFile(statusPath)
	if err != nil {
		return false
	}
	var status struct {
		Active  bool   `json:"active"`
		Running bool   `json:"running"`
		State   string `json:"state"`
		Status  string `json:"status"`
	}
	if json.Unmarshal(data, &status) != nil {
		return false
	}
	state := strings.ToLower(strings.TrimSpace(status.State))
	statusValue := strings.ToLower(strings.TrimSpace(status.Status))
	return status.Active || status.Running || state == "active" || state == "running" || statusValue == "active" || statusValue == "running"
}

func maxTime(a, b time.Time) time.Time {
	if b.After(a) {
		return b
	}
	return a
}

// renderRightPanel 渲染右侧面板：Pipeline 卡片（仅检测到任务时）+ Subagents 卡片 + Context 卡片。
// 整体高度被钳制为 totalHeight，防止右侧面板撑高终端布局。
func (m appModel) renderRightPanel(width, totalHeight int) string {
	cardWidth := rightCardWidth(width)
	contentWidth := rightCardContentWidth(width)

	contextContent := m.renderContextCardContent(contentWidth)
	contextCard := rightCardStyle.Width(cardWidth).Render(contextContent)
	ctxH := lipgloss.Height(contextCard)

	cards := []string{}
	if m.pipelineState.detected {
		reservedSubagentsHeight := rightCardVerticalFrame + 1
		maxPipelineContentHeight := maxInt(1, totalHeight-ctxH-reservedSubagentsHeight-rightCardVerticalFrame)
		pipelineContentHeight := minInt(pipelineCardMaxContentHeight, maxPipelineContentHeight)
		pipelineContent := m.renderPipelineContent(contentWidth, pipelineContentHeight)
		pipelineCard := rightCardStyle.Width(cardWidth).Height(pipelineContentHeight).Render(pipelineContent)
		cards = append(cards, pipelineCard)

		subagentsContentHeight := maxInt(1, totalHeight-lipgloss.Height(pipelineCard)-ctxH-rightCardVerticalFrame)
		subagentsContent := m.renderSubagentsCardContentHeight(contentWidth, subagentsContentHeight)
		subagentsCard := rightCardStyle.Width(cardWidth).Height(subagentsContentHeight).Render(subagentsContent)
		cards = append(cards, subagentsCard)
	} else {
		subagentsContentHeight := maxInt(1, totalHeight-ctxH-rightCardVerticalFrame)
		subagentsContent := m.renderSubagentsCardContentHeight(contentWidth, subagentsContentHeight)
		cards = append(cards, rightCardStyle.Width(cardWidth).Height(subagentsContentHeight).Render(subagentsContent))
	}
	cards = append(cards, contextCard)

	joined := lipgloss.JoinVertical(lipgloss.Left, cards...)
	// Clamp the right panel to totalHeight so it never exceeds the terminal height.
	return lipgloss.NewStyle().
		Width(width).
		Height(totalHeight).
		MaxHeight(totalHeight).
		Render(joined)
}

// renderContextCard 返回 Context 卡片（用于测试）。
func (m appModel) renderContextCard(width int) string {
	cardWidth := rightCardWidth(width)
	contentWidth := rightCardContentWidth(width)
	return rightCardStyle.Width(cardWidth).Render(m.renderContextCardContent(contentWidth))
}

func rightCardWidth(totalWidth int) int {
	return maxInt(4, totalWidth-rightCardBorderFrame)
}

func rightCardContentWidth(totalWidth int) int {
	return maxInt(1, rightCardWidth(totalWidth)-rightCardHorizontalPadding)
}

// renderSubagentsCardContent 渲染 Subagents 内容（Task 4 实现）。
func (m appModel) renderSubagentsCardContent(width int) string {
	return m.renderSubagentsCardContentHeight(width, 0)
}

func (m appModel) renderSubagentsCardContentHeight(width, height int) string {
	hdrStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("250")).Bold(true)
	mutedStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("246"))
	hdr := renderSidebarRow(width, "subagents", "", hdrStyle, mutedStyle)
	maxLines := height

	if m.subagents == nil {
		if maxLines == 1 {
			return hdr
		}
		return hdr + "\n" + mutedStyle.Italic(true).Render(padDisplayWidth("none", width))
	}
	tasks := m.subagentTasks()
	if len(tasks) == 0 {
		if maxLines == 1 {
			return hdr
		}
		empty := mutedStyle.Italic(true).Render(padDisplayWidth("none", width))
		return hdr + "\n" + empty
	}

	dotRunStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("84"))
	dotDoneStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("245"))
	dotFailStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("203"))
	dotStopStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("214"))

	availableTaskRows := len(tasks)
	moreCount := 0
	if maxLines > 0 {
		availableTaskRows = maxInt(0, maxLines-1)
		if len(tasks) > availableTaskRows {
			if availableTaskRows <= 1 {
				moreCount = len(tasks)
				availableTaskRows = 0
			} else {
				availableTaskRows--
				moreCount = len(tasks) - availableTaskRows
			}
		}
	}

	lines := []string{hdr}
	for _, t := range tasks[:minInt(len(tasks), availableTaskRows)] {
		var dot, status string
		dotStyle := dotDoneStyle
		lineStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("248"))
		noDot := false
		switch t.Status {
		case subagent.TaskRunning:
			noDot = true
			status = formatElapsedTime(time.Since(t.StartedAt))
			dotStyle = dotRunStyle
			lineStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("84"))
		case subagent.TaskFailed:
			dot = "✗"
			status = "failed"
			dotStyle = dotFailStyle
			lineStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("203"))
		case subagent.TaskStopped:
			dot = "■"
			status = "stopped"
			dotStyle = dotStopStyle
			lineStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("214"))
		default:
			dot = "✓"
			status = "done"
		}
		nameStyle := lineStyle
		if color := strings.TrimSpace(t.Color); color != "" {
			nameStyle = lipgloss.NewStyle().Foreground(lipgloss.Color(color))
		}
		if noDot {
			lines = append(lines, renderSidebarRow(width, taskDisplayName(t), status, nameStyle, lineStyle))
		} else {
			lines = append(lines, renderSubagentSidebarRow(width, dot, taskDisplayName(t), status, dotStyle, nameStyle, lineStyle))
		}
	}
	if moreCount > 0 {
		lines = append(lines, renderSidebarRow(width, fmt.Sprintf("+%d more", moreCount), "", mutedStyle, mutedStyle))
	}
	return strings.Join(lines, "\n")
}

// renderPipelineOrTasksContent 保留给测试和旧调用点：无 pipeline 时返回空内容。
func (m appModel) renderPipelineOrTasksContent(width, height int) string {
	if m.pipelineState.detected {
		return m.renderPipelineContent(width, height)
	}
	return ""
}

func (m appModel) renderPipelineContent(width, height int) string {
	return m.renderPipelineWindowedContent(width, height)
}

// renderPipelineWindowedContent 渲染满宽 Pipeline 仪表盘：摘要、阶段进度条和 timeline。
func (m appModel) renderPipelineWindowedContent(width, height int) string {
	ps := m.pipelineState

	currentIdx := ps.activeIdx
	if currentIdx < 0 {
		currentIdx = maxInt(0, ps.doneCount-1)
	}
	currentName := ""
	if currentIdx >= 0 && currentIdx < len(ps.phases) {
		currentName = ps.phases[currentIdx].name
	}
	if currentName == "" {
		currentName = "idle"
	}

	titleRight := currentName
	if ps.globalIter > 0 {
		titleRight = fmt.Sprintf("%s ×%d", titleRight, ps.globalIter)
	}

	pendingCount := 0
	retryCount := 0
	activeCount := 0
	for _, ph := range ps.phases {
		switch ph.status {
		case phaseStatusActive:
			activeCount++
		case phaseStatusRetry:
			retryCount++
		case phaseStatusPending:
			pendingCount++
		}
	}

	total := len(ps.phases)
	percent := 0
	if total > 0 {
		percent = int(float64(ps.doneCount) / float64(total) * 100)
	}

	lines := []string{
		renderSidebarRow(width, "pipeline", titleRight, lipgloss.NewStyle().Foreground(lipgloss.Color("250")).Bold(true), lipgloss.NewStyle().Foreground(lipgloss.Color("75")).Bold(true)),
		renderSidebarRow(width, fmt.Sprintf("%d/%d complete", ps.doneCount, total), fmt.Sprintf("%d%%", percent), lipgloss.NewStyle().Foreground(lipgloss.Color("246")), lipgloss.NewStyle().Foreground(lipgloss.Color("246"))),
		renderPipelineProgressBar(ps, width),
		renderSidebarRow(width, fmt.Sprintf("ok %d", ps.doneCount), fmt.Sprintf("now %d", activeCount), lipgloss.NewStyle().Foreground(lipgloss.Color("28")), lipgloss.NewStyle().Foreground(lipgloss.Color("75"))),
		renderSidebarRow(width, fmt.Sprintf("todo %d", pendingCount), fmt.Sprintf("retry %d", retryCount), lipgloss.NewStyle().Foreground(lipgloss.Color("246")), lipgloss.NewStyle().Foreground(lipgloss.Color("214"))),
		renderSidebarRow(width, "timeline", "near", lipgloss.NewStyle().Foreground(lipgloss.Color("250")).Bold(true), lipgloss.NewStyle().Foreground(lipgloss.Color("246"))),
	}

	stageRows := minInt(pipelineMaxStageRows, maxInt(0, height-len(lines)))
	for _, idx := range visiblePipelineStageIndices(ps, stageRows) {
		lines = append(lines, renderPipelineStageLine(ps.phases[idx], idx, currentIdx, width))
	}
	return strings.Join(lines, "\n")
}

func renderPipelineProgressBar(ps pipelineState, width int) string {
	width = maxInt(1, width)
	total := len(ps.phases)
	if total == 0 {
		return strings.Repeat("▱", width)
	}
	parts := make([]string, 0, width)
	for cell := 0; cell < width; cell++ {
		idx := minInt(total-1, cell*total/width)
		status := ps.phases[idx].status
		if status == phaseStatusActive && (cell == 0 || minInt(total-1, (cell-1)*total/width) != idx) {
			parts = append(parts, lipgloss.NewStyle().Foreground(lipgloss.Color("75")).Bold(true).Render("▶"))
			continue
		}
		switch status {
		case phaseStatusDone:
			parts = append(parts, lipgloss.NewStyle().Foreground(lipgloss.Color("28")).Render("▰"))
		case phaseStatusActive:
			parts = append(parts, lipgloss.NewStyle().Foreground(lipgloss.Color("75")).Render("▰"))
		case phaseStatusRetry:
			parts = append(parts, lipgloss.NewStyle().Foreground(lipgloss.Color("214")).Render("▱"))
		default:
			parts = append(parts, lipgloss.NewStyle().Foreground(lipgloss.Color("245")).Render("▱"))
		}
	}
	return strings.Join(parts, "")
}

func visiblePipelineStageIndices(ps pipelineState, available int) []int {
	total := len(ps.phases)
	if available <= 0 {
		return nil
	}
	if available >= total {
		indices := make([]int, total)
		for i := range indices {
			indices[i] = i
		}
		return indices
	}
	center := ps.activeIdx
	if center < 0 {
		center = maxInt(0, ps.doneCount-1)
	}
	start := center - available/2
	start = maxInt(0, minInt(start, total-available))
	indices := make([]int, available)
	for i := range indices {
		indices[i] = start + i
	}
	return indices
}

func renderPipelineStageLine(ph pipelinePhaseEntry, idx, currentIdx, width int) string {
	symbol, status := pipelineStageGlyphAndStatus(ph.status)
	name := ph.name
	if ph.iteration > 0 {
		name = fmt.Sprintf("%s ×%d", name, ph.iteration)
	}
	left := symbol + " " + name
	if idx == currentIdx {
		contentWidth := maxInt(1, width-1)
		content := renderSidebarRow(contentWidth, left, status, lipgloss.NewStyle().Foreground(lipgloss.Color("252")).Bold(true), lipgloss.NewStyle().Foreground(lipgloss.Color("252")))
		return lipgloss.NewStyle().Foreground(lipgloss.Color("68")).Render("▐") +
			lipgloss.NewStyle().Width(contentWidth).Background(lipgloss.Color("234")).Render(content)
	}
	var fg lipgloss.Color
	switch ph.status {
	case phaseStatusDone:
		fg = lipgloss.Color("248")
	case phaseStatusRetry:
		fg = lipgloss.Color("214")
	case phaseStatusActive:
		fg = lipgloss.Color("252")
	default:
		fg = lipgloss.Color("245")
	}
	style := lipgloss.NewStyle().Foreground(fg)
	return renderSidebarRow(width, left, status, style, style)
}

func pipelineStageGlyphAndStatus(status pipelinePhaseStatus) (string, string) {
	switch status {
	case phaseStatusDone:
		return "✓", "done"
	case phaseStatusActive:
		return "▶", "now"
	case phaseStatusRetry:
		return "↻", "retry"
	default:
		return "·", "pending"
	}
}

func renderSidebarRow(width int, left, right string, leftStyle, rightStyle lipgloss.Style) string {
	width = maxInt(1, width)
	if width <= 2 || strings.TrimSpace(right) == "" {
		return leftStyle.Render(padDisplayWidth(truncateDisplayWidth(left, width), width))
	}
	right = truncateDisplayWidth(right, maxInt(1, width/2))
	rightWidth := lipgloss.Width(right)
	leftMax := maxInt(1, width-rightWidth-1)
	left = truncateDisplayWidth(left, leftMax)
	gap := maxInt(0, width-lipgloss.Width(left)-rightWidth)
	return leftStyle.Render(left) + strings.Repeat(" ", gap) + rightStyle.Render(right)
}

func renderSubagentSidebarRow(width int, dot, name, right string, dotStyle, nameStyle, rightStyle lipgloss.Style) string {
	width = maxInt(1, width)
	right = strings.TrimSpace(right)
	if width <= 2 || right == "" {
		return renderSubagentSidebarLeft(width, dot, name, dotStyle, nameStyle)
	}
	right = truncateDisplayWidth(right, maxInt(1, width/2))
	rightWidth := lipgloss.Width(right)
	leftMax := maxInt(1, width-rightWidth-1)
	left := renderSubagentSidebarLeft(leftMax, dot, name, dotStyle, nameStyle)
	gap := maxInt(0, width-lipgloss.Width(left)-rightWidth)
	return left + strings.Repeat(" ", gap) + rightStyle.Render(right)
}

func renderSubagentSidebarLeft(width int, dot, name string, dotStyle, nameStyle lipgloss.Style) string {
	width = maxInt(1, width)
	dot = truncateDisplayWidth(dot, width)
	dotWidth := lipgloss.Width(dot)
	if width <= dotWidth+1 {
		return dotStyle.Render(padDisplayWidth(dot, width))
	}
	nameWidth := maxInt(1, width-dotWidth-1)
	name = truncateDisplayWidth(name, nameWidth)
	left := dotStyle.Render(dot) + " " + nameStyle.Render(name)
	if lipgloss.Width(left) >= width {
		return left
	}
	return left + strings.Repeat(" ", width-lipgloss.Width(left))
}

func padDisplayWidth(text string, width int) string {
	if lipgloss.Width(text) >= width {
		return text
	}
	return text + strings.Repeat(" ", width-lipgloss.Width(text))
}

func formatElapsedTime(d time.Duration) string {
	s := int(d.Seconds())
	if s < 0 {
		s = 0
	}
	if s < 60 {
		return fmt.Sprintf("%ds", s)
	}
	h := s / 3600
	m := (s % 3600) / 60
	sec := s % 60
	if h > 0 {
		return fmt.Sprintf("%dh %dm %ds", h, m, sec)
	}
	return fmt.Sprintf("%dm %ds", m, sec)
}
